  if(a==='plus'||a==='minus'){if(state.shared&&state.room?.menu){cartQueue=cartQueue.catch(()=>{}).then(async()=>{const r=await sharedCall('delta',{itemId:el.dataset.id,delta:a==='plus'?1:-1,operationId:crypto.randomUUID()});sharedState(r.room);});await cartQueue;return;}const id=el.dataset.id;state.cart[id]=Math.max(0,Math.min(99,(state.cart[id]||0)+(a==='plus'?1:-1)));if(!state.cart[id])delete state.cart[id];render();return;}
