function bind(){document.querySelectorAll('[data-food-card]').forEach(card=>{const open=()=>action('detail',card).catch(e=>{state.error=e.message;render();});card.addEventListener('click',e=>{if(e.target.closest('button,a,input,select,textarea'))return;open();});card.addEventListener('keydown',e=>{if(e.target!==card||!['Enter',' '].includes(e.key))return;e.preventDefault();open();});});$('#catalog-category')?.addEventListener('change',e=>{state.catalogCategory=e.target.value;state.catalogPage=0;render();});$('#include-tip')?.addEventListener('change',e=>{state.tipEnabled=e.target.checked;render();});$('#tip-percent')?.addEventListener('change',e=>{state.tipOverride=Number(e.target.value);state.tipEnabled=true;render();});$('#friend-form')?.addEventListener('submit',e=>{e.preventDefault();const name=$('#friend-name').value.trim();if(!name)return;const old=state.friends.find(f=>f.id===state.editFriendId);const friend={id:old?.id||crypto.randomUUID(),name,preference:$('#friend-preference').value.trim(),allergies:$('#friend-allergies').value.trim(),dislikes:$('#friend-dislikes').value.trim(),example:false};if(old)state.friends=state.friends.map(f=>f.id===friend.id?friend:f);else state.friends.push(friend);state.companions=state.companions.map(c=>c.id===friend.id?{...friend}:c);save();go('companions');toast('입맛을 저장했어요.');});$('#order-request')?.addEventListener('input',e=>{state.requestText=e.target.value;state.orderStale=true;translationRevision++;clearTimeout(translationTimer);$('#request-status').textContent='입력이 끝나면 자동으로 번역해요.';document.querySelector('[data-action="staff"]')?.setAttribute('disabled','');translationTimer=setTimeout(()=>translateOrder().catch(()=>{}),900);});const searchInput=$('#destination-query');searchInput?.addEventListener('input',e=>{state.destinationQuery=e.target.value;destinationRequest++;clearTimeout(destinationTimer);destinationTimer=setTimeout(findDestinations,300);});$('#destination-form')?.addEventListener('submit',e=>{e.preventDefault();clearTimeout(destinationTimer);findDestinations();});document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>action(el.dataset.action,el).catch(e=>{state.error=e.message;render();})));$('#country')?.addEventListener('change',e=>state.language=e.target.value);$('#consent')?.addEventListener('change',e=>{state.consent=e.target.checked;localStorage.setItem(state.config.gemini?'gourmet-gemini-consent':'gourmet-photo-consent',JSON.stringify(state.consent));document.querySelector('[data-action=recognize]').disabled=!state.consent||!state.photos.length;});$('#file').onchange=e=>{const files=[...e.target.files];e.target.value='';void addFiles(files);};$('#search-form')?.addEventListener('submit',e=>{e.preventDefault();const query=$('#query').value.trim();work('식당을 검색하고 있어요',()=>search(query));});$('#companion-form')?.addEventListener('submit',e=>{e.preventDefault();state.companions.push({name:$('#name').value.trim(),preference:$('#preference').value.trim(),allergies:$('#allergies').value.trim()});save();render();});document.querySelectorAll('.art img').forEach(img=>img.addEventListener('error',()=>{img.parentNode.textContent='🍽';const article=img.closest('article');if(article){const s=article.querySelectorAll('.source');if(s[1])s[1].textContent='사진을 불러오지 못했습니다 · 삽화 아이콘';}}));}
window.addEventListener('pagehide',stopCamera);
window.addEventListener('pageshow',()=>{if(state.screen==='capture'){state.cameraError='';void cameraOn();}});
window.addEventListener('keydown',e=>{if(state.screen==='detail'&&e.key==='Escape')go(state.detailSource==='catalog'?'officialCatalog':state.detailSource==='favorites'?'favorites':'menu');});
const preview=new URLSearchParams(location.search).get('design');
if(['capture','restaurant','review','menu','detail','cart','order','staff'].includes(preview)){state.demo=true;state.menu={restaurantName:'TRATTORIA',language:'it',currency:'EUR',items:structuredClone(demoItems)};state.photos=['/demo.svg'];state.cart={'0':1};state.screen=preview;state.detail=state.menu.items[0];state.detailSource='menu';state.order={text:'Vorremmo ordinare una porzione di Baccalà alla Fiorentina, per favore.',pronunciation:'보렘모 오르디나레 우나 포르치오네 디 바깔라 알라 피오렌티나, 페르 파보레.',korean:'피렌체식 염장 대구 요리 1인분 주세요.',language:'it'};}
if(new URLSearchParams(location.search).get('capture')==='1'){state.screen='capture';state.demo=false;state.photos=[];state.menu=null;}
const captureFileInput=document.createElement('input');captureFileInput.id='file';captureFileInput.type='file';captureFileInput.accept='image/jpeg,image/png,image/webp';captureFileInput.multiple=true;captureFileInput.className='visually-hidden';document.body.append(captureFileInput);
render();configReady=fetch('/api/config',{signal:AbortSignal.timeout(12000)}).then(r=>r.json()).then(c=>{state.config=c;state.consent=read(c.gemini?'gourmet-gemini-consent':'gourmet-photo-consent',false);render();}).catch(()=>{state.error='서버에 연결되지 않았습니다. 실행 방법을 확인해주세요.';render();});

async function initializeShared(){const hash=new URLSearchParams(location.hash.slice(1));try{if(hash.get('together')&&hash.get('invite')){const r=await api('shared/join',{roomId:hash.get('together'),invite:hash.get('invite')});state.shared={roomId:r.room.id,token:r.token,memberId:r.memberId};rememberShared();sharedState(r.room);window.history.replaceState(null,'',location.pathname+location.search);go(r.room.menu?'menu':'companions');toast('함께 담는 장바구니에 연결됐어요.');}else if(state.shared&&!preview){const r=await sharedCall('get');sharedState(r.room);}}catch(e){state.shared=null;localStorage.removeItem('gourmet-shared');state.sharedError=e.message;}sharedTimer=setInterval(pollShared,1500);}
void initializeShared();

setInterval(()=>{if(!document.hidden&&["menu","cart","detail"].includes(state.screen))void loadExchangeRate();},60000);
if(new URLSearchParams(location.search).get('official-menu')==='solita-zuppa'){state.catalogReturn='home';void api('restaurant-catalog',{}).then(c=>{state.catalog=c;state.catalogPage=0;state.catalogCategory='';go('officialCatalog');}).catch(e=>{state.error=e.message;render();});}
